 @Test void concurrentDefaultSwitchHasExactlyOneWinnerDefault()throws Exception{var u=student();String room=room("PRIVATE").get("id").asText();var a=address(u,room);var b=address(u,room);try(var pool=Executors.newFixedThreadPool(2)){var x=pool.submit(()->raw("POST",baseAddress()+"/"+a.get("id").asText()+"/default",u.token(),Map.of("version",a.get("version").asInt())));var y=pool.submit(()->raw("POST",baseAddress()+"/"+b.get("id").asText()+"/default",u.token(),Map.of("version",b.get("version").asInt())));assertTrue(Set.of(200,409).contains(x.get().status()));assertTrue(Set.of(200,409).contains(y.get().status()));}assertEquals(1,jdbc.queryForObject("select count(*) from public.user_address where user_id=? and enabled and is_default",Integer.class,u.id()));}
 record PrivateAsset(String id,String token,String room){}
 PrivateAsset privateAsset()throws Exception{var asset=asset();var r=room("PRIVATE");long room=Long.parseLong(r.get("id").asText());long floor=jdbc.queryForObject("select floor_id from public.room where id=?",Long.class,room);long building=jdbc.queryForObject("select building_id from public.building_floor where id=?",Long.class,floor);jdbc.update("update public.facility set building_id=?,floor_id=?,room_id=?,public_zone=null where id=?",building,floor,room,Long.parseLong(asset.id()));return new PrivateAsset(asset.id(),asset.payload().substring(asset.payload().lastIndexOf('/')+1),Long.toString(room));}
 @Test void verifiedResidentAccessImmediateRevocationAndCrossDormitory()throws Exception{var a=student();var b=student();var f=privateAsset();call("GET","/api/v2/facilities/"+f.id(),a.token(),null,404);address(a,f.room());call("GET","/api/v2/facilities/resolve/"+f.token(),a.token(),null,404);var rr=grant(a,f.room());assertEquals(1,call("GET","/api/v2/facilities",a.token(),null,200).get("total").asInt());call("GET","/api/v2/facilities/"+f.id(),a.token(),null,200);call("GET","/api/v2/facilities/resolve/"+f.token(),a.token(),null,200);call("GET","/api/v2/facilities/"+f.id(),b.token(),null,404);call("PATCH","/api/v2/residencies/"+rr.get("id").asText(),admin,Map.of("version",0,"enabled",false),200);call("GET","/api/v2/facilities/resolve/"+f.token(),a.token(),null,404);assertEquals(0,call("GET","/api/v2/facilities",a.token(),null,200).get("total").asInt());}
