 @Test void incompleteDraftHasNoFormalSideEffectsAndAbandon()throws Exception{var u=student();int orders=jdbc.queryForObject("select count(*) from public.repair_order",Integer.class);int records=jdbc.queryForObject("select count(*) from public.repair_record",Integer.class);var d=call("POST","/api/v2/drafts",u.token(),Map.of(),200);assertFalse(d.get("complete").asBoolean());assertFalse(d.get("formalSubmissionAvailable").asBoolean());call("POST","/api/v2/drafts/"+d.get("id").asText()+"/abandon",u.token(),Map.of("version",1),200);call("PUT","/api/v2/drafts/"+d.get("id").asText(),u.token(),Map.of("version",2),409);assertEquals(orders,jdbc.queryForObject("select count(*) from public.repair_order",Integer.class));assertEquals(records,jdbc.queryForObject("select count(*) from public.repair_record",Integer.class));assertEquals(0,jdbc.queryForObject("select count(*) from information_schema.tables where table_schema='public' and table_name like 'act_%'",Integer.class));}
 @Test void immutableRevisionAndCrossOwnerPrivacy()throws Exception{var a=student();var b=student();var d=call("POST","/api/v2/drafts",a.token(),Map.of("description","First"),200);String path="/api/v2/drafts/"+d.get("id").asText();call("PUT",path,a.token(),Map.of("version",1,"description","Second"),200);var history=call("GET",path+"/revisions",a.token(),null,200);assertEquals(2,history.get("total").asInt());assertEquals("First",history.get("items").get(1).get("description").asText());call("GET",path,b.token(),null,404);call("GET",path,admin,null,404);assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("update public.repair_draft_revision set description='Changed' where draft_id=?",Long.parseLong(d.get("id").asText())));}
 @Test void snapshotsDefaultEstimateAndSourceEdits()throws Exception{var u=student();var r=room("PRIVATE");var address=address(u,r.get("id").asText());var item=item(newUsername());var d=call("POST","/api/v2/drafts",u.token(),Map.of("description","Synthetic fault","itemId",item.get("id").asText(),"useDefaultAddress",true),200);String path="/api/v2/drafts/"+d.get("id").asText();assertTrue(d.get("complete").asBoolean());call("PATCH",baseAddress()+"/"+address.get("id").asText(),u.token(),Map.of("version",address.get("version").asInt(),"contactName","New contact","phone","00000000001"),200);jdbc.update("update public.repair_item set name='Source renamed',estimated_minutes=90 where id=?",Long.parseLong(item.get("id").asText()));var revision=call("GET",path,u.token(),null,200).get("revision");assertEquals("Synthetic contact",revision.get("addressSnapshot").get("contactName").asText());assertEquals(30,revision.get("estimatedMinutes").asInt());assertEquals("ITEM_DEFAULT",revision.get("estimateSource").asText());assertFalse(revision.get("unattendedWilling").asBoolean());}
 @Test void windowsAndManualEstimateAreVersioned()throws Exception{var u=student();call("POST","/api/v2/drafts",u.token(),Map.of("timeMode","WINDOW"),400);call("POST","/api/v2/drafts",u.token(),Map.of("timeMode","WINDOW","windowStart","2026-12-01T10:00:00","windowEnd","2026-12-01T11:00:00"),400);var d=call("POST","/api/v2/drafts",u.token(),Map.of("timeMode","WINDOW","windowStart","2026-12-01T10:00:00+08:00","windowEnd","2026-12-01T11:00:00+08:00","unattendedWilling",true,"estimatedMinutes",45,"estimateReason","Synthetic estimate"),200);String path="/api/v2/drafts/"+d.get("id").asText();call("PUT",path,u.token(),Map.of("version",1,"timeMode","ANY","unattendedWilling",false),200);var history=call("GET",path+"/revisions",u.token(),null,200);assertEquals("MANUAL",history.get("items").get(1).get("estimateSource").asText());assertFalse(history.get("items").get(0).get("unattendedWilling").asBoolean());}
 @Test void draftConcurrentConflictAndAuditFailureRollback()throws Exception{var u=student();var d=call("POST","/api/v2/drafts",u.token(),Map.of(),200);String path="/api/v2/drafts/"+d.get("id").asText();try(var pool=Executors.newFixedThreadPool(2)){var x=pool.submit(()->raw("PUT",path,u.token(),Map.of("version",1,"description","A")));var y=pool.submit(()->raw("PUT",path,u.token(),Map.of("version",1,"description","B")));assertEquals(Set.of(200,409),Set.of(x.get().status(),y.get().status()));}doThrow(new IllegalStateException("Injected")).when(auditTarget).record(any(),eq("DRAFT_REVISION_SAVED"),anyString(),any(),anyMap());call("PUT",path,u.token(),Map.of("version",2,"description","Rollback"),500);assertEquals(2,call("GET",path+"/revisions",u.token(),null,200).get("total").asInt());}

 @Test void facilityItemAndAddressMustMatchAndSnapshotsRemainStable()throws Exception{var u=student();var f=privateAsset();grant(u,f.room());var addr=address(u,f.room());String item=jdbc.queryForObject("select t.item_id::text from public.facility_type_repair_item t join public.facility f on f.facility_type_id=t.type_id where f.id=? limit 1",String.class,Long.parseLong(f.id()));var d=call("POST","/api/v2/drafts",u.token(),Map.of("description","Synthetic facility fault","itemId",item,"facilityId",f.id(),"addressId",addr.get("id").asText()),200);String path="/api/v2/drafts/"+d.get("id").asText();var original=call("GET",path,u.token(),null,200).get("revision");var movedBuilding=building(campus().get("id").asText());jdbc.update("update public.facility set name='Later renamed',building_id=?,floor_id=null,room_id=null,public_zone='SYNTHETIC_MOVED_ZONE' where id=?",Long.parseLong(movedBuilding.get("id").asText()),Long.parseLong(f.id()));jdbc.update("update public.repair_category set name='Later category' where id=(select category_id from public.repair_item where id=?)",Long.parseLong(item));assertEquals(original,call("GET",path,u.token(),null,200).get("revision"));var wrongItem=item(newUsername());call("POST","/api/v2/drafts",u.token(),Map.of("facilityId",f.id(),"itemId",wrongItem.get("id").asText()),400);var wrongAddress=address(u,room("PRIVATE").get("id").asText());call("POST","/api/v2/drafts",u.token(),Map.of("facilityId",f.id(),"addressId",wrongAddress.get("id").asText()),400);}
